&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Wingdings&quot; data-listid=&quot;9&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:1676984,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:227,&amp;quot;335559991&amp;quot;:227,&amp;quot;469769226&amp;quot;:&amp;quot;Wingdings&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt;Identify&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt; and build consultative relationships with key clients and stakeholders across the National Security community, to enable further sales opportunities&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
